}

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn main() -> i64 with IO, Mut, Div, Panic {
    var z: [f64; 16] = [0.0; 16]
    var w: [f64; 16] = [0.0; 16]
    sed_canonical_zd_pair(&!z, &!w)
    var e1s: [f64; 16] = [0.0; 16]
