    var ok: i64 = 1
    if sed_lmul_product_nsq(&z, &w) > 1.0e-9 { ok = 0 }
    if sed_lmul_product_nsq(&w, &z) > 1.0e-9 { ok = 0 }
    if abs_f(sed_lmul_product_nsq(&z, &z) - 4.0) > 1.0e-9 { ok = 0 }
    if abs_f(sed_lmul_product_nsq(&w, &w) - 4.0) > 1.0e-9 { ok = 0 }
    if sed_lmul_composed_nsq(&z, &w, &e1s) > 1.0e-9 { ok = 0 }
    if abs_f(sed_lmul_sequential_nsq(&z, &w, &e1s) - 8.0) > 1.0e-9 { ok = 0 }
    if sed_rmul_composed_nsq(&z, &w, &e1s) > 1.0e-9 { ok = 0 }
    if abs_f(sed_rmul_sequential_nsq(&z, &w, &e1s) - 8.0) > 1.0e-9 { ok = 0 }

    var e1o = oct_basis(1)
    var e2o = oct_basis(2)
    var e1e: [f64; 16] = [0.0; 16]
    var e2e: [f64; 16] = [0.0; 16]
    sed_embed_oct(&e1o, &!e1e)
    sed_embed_oct(&e2o, &!e2e)
    if abs_f(sed_lmul_product_nsq(&e1e, &e2e) - 1.0) > 1.0e-9 { ok = 0 }
    if abs_f(sed_lmul_product_nsq(&e2e, &e1e) - 1.0) > 1.0e-9 { ok = 0 }

    if ok == 1 { 0 } else { 1 }
}

//@ run-pass
// Phase 0 of epistemic-length Seq<T>: heap-backed growable sequence.
//   seq_new() -> Seq          (capacity 4, len 0, confidence 1.0)
//   seq_push(s, v)            grow-on-full (mremap), pointer written back
//   seq_get(s, i) -> T
//   seq_set(s, i, v)
//   seq_len(s) -> Knowledge<i64>   (value = len, with epistemic confidence)
// Phase 0: elem_size fixed at 8 (scalar Seq<i64>); push receiver is a local var.

fn main() -> i32 with IO, Mut, Panic, Epistemic {
    var s: Seq<i64> = seq_new()
    seq_push(s, 10)
    seq_push(s, 20)
    seq_push(s, 30)

    if seq_get(s, 0) != 10 { println("seq_basic: FAIL (get 0)"); return 1 }
    if seq_get(s, 1) != 20 { println("seq_basic: FAIL (get 1)"); return 1 }
    if seq_get(s, 2) != 30 { println("seq_basic: FAIL (get 2)"); return 1 }

    let k = seq_len(s)
    if k.unwrap("len") != 3 { println("seq_basic: FAIL (len)"); return 1 }

    // seq_set overwrites in place
    seq_set(s, 1, 99)
    if seq_get(s, 1) != 99 { println("seq_basic: FAIL (set)"); return 1 }

    // ---- grow past initial capacity (4) to force mremap + pointer writeback ----
    var g: Seq<i64> = seq_new()
    var i = 0
    while i < 20 {
        seq_push(g, i * 7)
        i = i + 1
    }
    let gk = seq_len(g)
    if gk.unwrap("len") != 20 { println("seq_basic: FAIL (grow len)"); return 1 }
    // verify every element survived the realloc(s)
    var j = 0
    while j < 20 {
        if seq_get(g, j) != j * 7 {
            println("seq_basic: FAIL (grow element)")
            return 1
        }
        j = j + 1
    }

    println("seq_basic: PASS")
    return 0
}

//@ run-pass
//@ expect-stdout-contains: seq_knowledge_uncertain: PASS
//@ description: seq_push_uncertain into a Seq<Knowledge<f64>> stores a real Knowledge element
//@ requires: lean_single
// `seq_push_uncertain` exists only in the lean_single bootstrap surface
// (self-hosted/compiler/lean_single.sio). Madaros never implemented it: its Seq
// method lowering has an explicit arm that refuses `.push_uncertain(...)`, and
// the free-function spelling used here does not resolve at all, so the file
// reports E137 rather than the refusal. Measured 2026-09-04 on the committed
// bin/madaros-linux-x86_64; the name has no definition anywhere in the tree.
// Same shape as tests/compile-fail/refinement_subtype_strict.sio: the feature
// lives in the seed, so the test must not run on the Madaros job.
//
// Regression for the Lane C SIGSEGV: seq_push_uncertain passed its raw f64 `value`
// to seq_materialize_push_value, which — because type_is_struct_like(0, knowledge_hash)
// is true — heap-copied 24 bytes treating the f64 bits as a Knowledge-block pointer and
// crashed. The fix assembles a real Knowledge block {value@0, variance@8, confidence@16}
// from the (value, confidence, variance) scalars (same representation as .push(measure(..)))
// and materializes that, so per-element reads work and the additive header aggregate
// (Σ variance, min confidence) is preserved. (Seq<i64>/Seq<f64> were never affected;
// see seq_epistemic.sio.)

fn main() with IO, Alloc, Mut, Epistemic {
    var s: Seq<Knowledge<f64>> = seq_new()
    seq_push_uncertain(s, 10.0, 0.9, 4.0)
    seq_push_uncertain(s, 20.0, 0.8, 1.0)
    seq_push_uncertain(s, 30.0, 0.95, 0.25)

    var i: i64 = 0
    var sum: f64 = 0.0
    while i < s.count() {
        sum = sum + acknowledge(s[i], "batch read")
        i = i + 1
    }

    // aggregate read-back (header Σvariance / min-confidence) must not crash
    let agg = seq_len(s)
    let n: i64 = acknowledge(agg, "count")

    var ok: i64 = 1
    if s.count() != 3 { ok = 0 }
    if n != 3 { ok = 0 }
    if sum < 59.999 || sum > 60.001 { ok = 0 }   // 10 + 20 + 30

    if ok == 1 { print("seq_knowledge_uncertain: PASS\n") } else { print("seq_knowledge_uncertain: FAIL\n") }
}

