// Test 3: Build 5x5 tridiagonal and verify get()
fn test_tridiagonal_build() -> bool with IO, Mut, Panic, Div {
    // Tridiagonal: [-1, 2, -1] pattern (1D Laplacian)
    var lower: [f64; 128] = [0.0; 128]
    var main: [f64; 128] = [0.0; 128]
    var upper: [f64; 128] = [0.0; 128]

    var i = 0
    while i < 5 {
        main[i] = 2.0
        i = i + 1
    }
    i = 0
    while i < 4 {
        lower[i] = 0.0 - 1.0
        upper[i] = 0.0 - 1.0
        i = i + 1
    }

    let t = sparse_tridiagonal(lower, main, upper, 5)

    // Verify structure
    let ok_diag = abs_f64(sparse_get(t, 2, 2) - 2.0) < 1e-12
    let ok_sub = abs_f64(sparse_get(t, 2, 1) - (0.0 - 1.0)) < 1e-12
    let ok_sup = abs_f64(sparse_get(t, 2, 3) - (0.0 - 1.0)) < 1e-12
    let ok_zero = abs_f64(sparse_get(t, 0, 3)) < 1e-12
    let ok_corner = abs_f64(sparse_get(t, 4, 3) - (0.0 - 1.0)) < 1e-12

    // Verify nnz = 5*3 - 2 = 13 (corners lose one each)
    let ok_nnz = sparse_nnz(t) == 13

    print("  nnz=")
    println(sparse_nnz(t))
    print("  A[2,2]=")
    println(sparse_get(t, 2, 2))
    print("  A[2,1]=")
    println(sparse_get(t, 2, 1))

    return ok_diag && ok_sub && ok_sup && ok_zero && ok_corner && ok_nnz
}

