fn test_upper_triangular_solve() -> bool with IO, Mut, Panic, Div {
    // U = [[2, 1, 4],
    //      [0, 3, 5],
    //      [0, 0, 6]]
    var rows: [i32; 1024] = [0; 1024]
    var cols: [i32; 1024] = [0; 1024]
