    rows[2] = 0; cols[2] = 2; vals[2] = 4.0
    rows[3] = 1; cols[3] = 1; vals[3] = 3.0
    rows[4] = 1; cols[4] = 2; vals[4] = 5.0
    rows[5] = 2; cols[5] = 2; vals[5] = 6.0

    let u = sparse_from_triplets(rows, cols, vals, 6, 3, 3)

    // For x = [1, 2, 3]:
    // b[0] = 2*1 + 1*2 + 4*3 = 2+2+12 = 16
    // b[1] = 3*2 + 5*3 = 6+15 = 21
