// Test 9: Build from COO triplets, verify CSR structure
fn test_from_triplets() -> bool with IO, Mut, Panic, Div {
    // Build a 3x3 matrix with duplicates:
    // (0,0)=1, (0,0)=2 (duplicate -> sums to 3), (1,2)=5, (2,1)=7
    var rows: [i32; 1024] = [0; 1024]
    var cols: [i32; 1024] = [0; 1024]
    var vals: [f64; 1024] = [0.0; 1024]

    rows[0] = 0; cols[0] = 0; vals[0] = 1.0
    rows[1] = 0; cols[1] = 0; vals[1] = 2.0  // duplicate
    rows[2] = 1; cols[2] = 2; vals[2] = 5.0
    rows[3] = 2; cols[3] = 1; vals[3] = 7.0

    let a = sparse_from_triplets(rows, cols, vals, 4, 3, 3)

    // After merging duplicates: (0,0)=3, (1,2)=5, (2,1)=7
    let ok_dup = abs_f64(sparse_get(a, 0, 0) - 3.0) < 1e-12
    let ok_12 = abs_f64(sparse_get(a, 1, 2) - 5.0) < 1e-12
    let ok_21 = abs_f64(sparse_get(a, 2, 1) - 7.0) < 1e-12
    let ok_zero = abs_f64(sparse_get(a, 1, 1)) < 1e-12
    let ok_nnz = sparse_nnz(a) == 3

    print("  A[0,0]=")
    println(sparse_get(a, 0, 0))
    print("  nnz=")
    println(sparse_nnz(a))

    return ok_dup && ok_12 && ok_21 && ok_zero && ok_nnz
}

