// Test 12: CG on SPD tridiagonal: -u'' = f (1D Poisson-like)
fn test_cg_tridiagonal() -> bool with IO, Mut, Panic, Div {
    let n = 10

    // SPD tridiagonal: [2, -1; -1, 2, -1; ...; -1, 2]
    var lower: [f64; 128] = [0.0; 128]
    var main: [f64; 128] = [0.0; 128]
    var upper: [f64; 128] = [0.0; 128]

    var i = 0
    while i < n {
        main[i] = 2.0
        i = i + 1
    }
    i = 0
    while i < n - 1 {
        lower[i] = 0.0 - 1.0
        upper[i] = 0.0 - 1.0
        i = i + 1
    }

    let a = sparse_tridiagonal(lower, main, upper, n)

    // Choose a known solution x_exact = [1, 2, 3, ..., 10]
    // Compute b = A * x_exact
    var x_exact: [f64; 128] = [0.0; 128]
    i = 0
    while i < n {
        x_exact[i] = (i + 1) as f64
        i = i + 1
    }

    let b = sparse_matvec(a, x_exact, n)

    var x0: [f64; 128] = [0.0; 128]
    var x: [f64; 128] = [0.0; 128]
    var result = CGMeta { iterations: 0, residual: 0.0, converged: false }
    cg_solve_into(&!x, &!result, a, b, x0, n, 1e-8, 200)

    // Check solution accuracy
    var max_err = 0.0
    i = 0
    while i < n {
        let diff = abs_f64(x[i] - x_exact[i])
        if diff > max_err {
            max_err = diff
        }
        i = i + 1
    }

    print("  iters=")
    println(result.iterations)
    print("  max_err=")
    println(max_err)
    print("  residual=")
    println(result.residual)

    return result.converged && max_err < 1e-6
}

// Test 13: CG on 1D Poisson equation discretization
// -u'' = f on [0, 1], u(0) = u(1) = 0
// With f(x) = pi^2 * sin(pi*x), exact u(x) = sin(pi*x)
fn test_cg_poisson() -> bool with IO, Mut, Panic, Div {
    let n = 20
    let h = 1.0 / ((n + 1) as f64)
    let pi = 3.14159265358979323846

    // Build SPD tridiagonal: (1/h^2) * [2, -1; -1, 2, -1; ...; -1, 2]
    var lower: [f64; 128] = [0.0; 128]
    var main: [f64; 128] = [0.0; 128]
    var upper: [f64; 128] = [0.0; 128]

    let h2_inv = 1.0 / (h * h)
    var i = 0
    while i < n {
        main[i] = 2.0 * h2_inv
        i = i + 1
    }
    i = 0
    while i < n - 1 {
        lower[i] = 0.0 - h2_inv
        upper[i] = 0.0 - h2_inv
        i = i + 1
    }

    let a = sparse_tridiagonal(lower, main, upper, n)

    // RHS: f(x_i) = pi^2 * sin(pi * x_i)
    // Use Taylor series for sin(x) near small arguments
    // sin(x) = x - x^3/6 + x^5/120 - x^7/5040 + x^9/362880
    var b: [f64; 128] = [0.0; 128]
    i = 0
    while i < n {
        let xi = (i + 1) as f64 * h
        let arg = pi * xi
        // Compute sin(arg) via Taylor series (sufficient for arg in [0, pi])
        // Reduce to [0, pi/2]: sin(pi - x) = sin(x)
        var t = arg
        if t > pi / 2.0 {
            t = pi - t
        }
        let t2 = t * t
        let t3 = t2 * t
        let t5 = t3 * t2
        let t7 = t5 * t2
        let t9 = t7 * t2
        let t11 = t9 * t2
        let sin_t = t - t3 / 6.0 + t5 / 120.0 - t7 / 5040.0 + t9 / 362880.0 - t11 / 39916800.0
        b[i] = pi * pi * sin_t
        i = i + 1
    }

    var x0: [f64; 128] = [0.0; 128]
    var x: [f64; 128] = [0.0; 128]
    var result = CGMeta { iterations: 0, residual: 0.0, converged: false }
    cg_solve_into(&!x, &!result, a, b, x0, n, 1e-10, 500)

    // Check against exact solution u(x_i) = sin(pi * x_i)
    var max_err = 0.0
    i = 0
    while i < n {
        let xi = (i + 1) as f64 * h
        let arg = pi * xi
        var t = arg
        if t > pi / 2.0 {
            t = pi - t
        }
        let t2 = t * t
        let t3 = t2 * t
        let t5 = t3 * t2
        let t7 = t5 * t2
        let t9 = t7 * t2
        let t11 = t9 * t2
        let exact = t - t3 / 6.0 + t5 / 120.0 - t7 / 5040.0 + t9 / 362880.0 - t11 / 39916800.0
        let diff = abs_f64(x[i] - exact)
        if diff > max_err {
            max_err = diff
        }
        i = i + 1
    }

    print("  iters=")
    println(result.iterations)
    print("  max_err=")
    println(max_err)
    print("  converged=")
    if result.converged { println("true") } else { println("false") }

    // The discretization error is O(h^2) ~ 1/(21^2) ~ 0.002
    // So we expect the CG solution to match the exact solution within O(h^2)
    return result.converged && max_err < 0.01
}

